// UI-only fixture. Every value and source reference is fictional.
import { act, useState } from "react";
import { createRoot } from "react-dom/client";
import DecisionCardsPanel from "../../app/decision-cards-panel";
import type { DecisionCard } from "../../domain/decision-cards";
import "../../app/typography.css";
import "../../app/workspace-appearance.css";
import "../../app/premium-tokens.css";
import "../../app/premium-workspace.css";

const period = { from: "2026-10-05", to: "2026-10-11" };
const baseEvidence = { period, asOf: "2026-10-11", sources: [{ system: "Fictional reviewed records", recordIds: ["fixture-document-001"], currency: "CAD", recordCount: 1, referencesTruncated: false }], formula: "The calculation uses only the fictional contributing records listed below.", limitations: ["Fictional UI verification. No live business, accounting, provider or AI data is used."] };
const cards: DecisionCard[] = [
  { id: "fixture-bills", kind: "bills_due", title: "Which bills need cash this week?", status: "recorded", value: { amount: 124000, unit: "minor_currency", currency: "CAD" }, summary: "The fictional reviewed bills total this amount. Confirm the payment queue against recorded cash before paying.", evidence: { ...baseEvidence, sources: [{ ...baseEvidence.sources[0], system: "Fictional bill ledger", recordIds: Array.from({ length: 14 }, (_, index) => `fixture-bill-${String(index + 1).padStart(3, "0")}`), recordCount: 24, referencesTruncated: true }], formula: "Seven-day cash obligations = the sum of open bill balances due through the business date + 6 days, including overdue and disputed obligations." }, action: { label: "Review the payment queue against cash", destination: "BookLoQ" }, missingFields: [] },
  { id: "fixture-expiry", kind: "expiry_risk", title: "What may remain at its shelf-life date?", status: "estimate", value: { amount: 6400, unit: "minor_currency", currency: "CAD" }, summary: "Fictional projected remaining stock has this recorded cost. Demand assumptions do not prove future waste.", evidence: { ...baseEvidence, sources: [{ ...baseEvidence.sources[0], system: "Fictional lot inventory", recordIds: ["fixture-lot-001", "fixture-lot-002"], recordCount: 2 }], formula: "Estimated cost at risk = forecast remaining whole units × recorded lot unit cost.", limitations: [...baseEvidence.limitations, "Forecast demand is an assumption. Actual sales and shelf-life decisions need owner review."] }, action: { label: "Review lot rotation and replenishment", destination: "Inventory" }, missingFields: [] },
  { id: "fixture-cash", kind: "order_affordability", title: "Does this order fit reserved cash?", status: "unavailable", value: null, summary: "Cash and obligations are incomplete. An affordability result cannot be supported.", evidence: { ...baseEvidence, asOf: null, sources: [], formula: "Funding headroom = reviewed current purchasing capacity − the proposed immediate order cost." }, action: { label: "Review the order and cash commitments", destination: "BookLoQ" }, missingFields: ["current_bank_cash", "reviewed_dated_commitments", "proposed_order_amount"] },
  { id: "fixture-payout", kind: "payout_difference", title: "Does this reviewed payout match the bank?", status: "recorded", value: { amount: 0, unit: "minor_currency", currency: "CAD" }, summary: "The explicitly mapped fictional components equal the recorded deposit. This recorded zero differs from missing evidence.", evidence: { ...baseEvidence, sources: [{ ...baseEvidence.sources[0], system: "Fictional payout reconciliation", recordIds: ["fixture-deposit-001", `fixture-component-${"long-retained-reference-".repeat(10)}`], recordCount: 2 }], formula: "Reviewed settlement difference = recorded bank deposit − the sum of explicitly mapped signed settlement components." }, action: { label: "Review the mapped components and bank reference", destination: "Workflows" }, missingFields: [] },
];
const root = createRoot(document.getElementById("root")!);
function Preview() {
  const [theme, setTheme] = useState("dark"), [narrow, setNarrow] = useState(false), [fail, setFail] = useState(false), [notice, setNotice] = useState("");
  return <main className="operating-shell decision-review-preview" data-workspace-theme={theme} data-narrow={narrow}><header><p>LOCAL UI REVIEW · FICTIONAL RECORDS</p><h1>Trace the number. Review the next step.</h1><p>The production decision panel with recorded, estimated and missing evidence.</p></header><nav aria-label="Fictional preview controls"><button type="button" onClick={() => setTheme(value => value === "dark" ? "light" : "dark")}>Switch to {theme === "dark" ? "light" : "dark"}</button><button type="button" onClick={() => setNarrow(value => !value)}>{narrow ? "Use full width" : "Use a 360px column"}</button><label><input type="checkbox" checked={fail} onChange={event => setFail(event.target.checked)}/> Reject the next action</label></nav><DecisionCardsPanel cards={cards} onEvidence={async card => { await new Promise(resolve => setTimeout(resolve, 300)); setNotice(`Evidence selected: ${card.id}. Source date: ${card.evidence.asOf ?? "not supplied"}. Period: ${card.evidence.period?.from} to ${card.evidence.period?.to}. This fixture sends no request.`); }} onAction={async card => { await new Promise(resolve => setTimeout(resolve, 600)); if (fail) throw new Error("PRIVATE_FIXTURE_PROVIDER_ERROR"); setNotice(`Reviewed step selected: ${card.id}. The original dated evidence remains attached. No records were changed.`); }}/><p className="fixture-notice" role="status">{notice}</p></main>;
}

async function verify() {
  (globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
  const results: { name: string; passed: boolean; message?: string }[] = [];
  const assert = (value: unknown, message: string) => { if (!value) throw new Error(message); };
  const get = <T extends Element = HTMLElement>(selector: string) => { const element = document.querySelector<T>(selector); if (!element) throw new Error(`Missing ${selector}`); return element; };
  const click = async (element: HTMLElement) => { await act(async () => element.click()); };
  let calls = 0, selected: DecisionCard | undefined, resolveStep!: () => void, rejectStep!: (error: Error) => void;
  const onAction = (card: DecisionCard) => { calls++; selected = card; return new Promise<void>((resolve, reject) => { resolveStep = resolve; rejectStep = reject; }); };
  const render = async (canAct = true, narrow = false) => { await act(async () => root.render(<main className="operating-shell" data-workspace-theme="dark"><div id="decision-test-host" style={{ width: narrow ? "320px" : "100%", maxWidth: "100%" }}><DecisionCardsPanel cards={cards} onEvidence={async card => { selected = card; }} onAction={canAct ? onAction : undefined}/></div></main>)); };
  const cases: [string, () => Promise<void>][] = [
    ["Recorded, estimate and unavailable values retain distinct meanings", async () => { await render(); const panels = document.querySelectorAll(".source-decision-card"); assert(panels[0].textContent?.includes("Recorded calculation"), "Recorded status absent"); assert(panels[1].textContent?.includes("Planning estimate"), "Estimate status absent"); assert(panels[2].querySelector(".source-decision-value")?.textContent === "Needs more evidence", "Missing cash became a number"); assert(panels[3].querySelector(".source-decision-value")?.textContent?.includes("0.00"), "Known recorded zero was hidden"); }],
    ["Source disclosure preserves formula, dates, missing fields and truncated reference coverage", async () => { await click(get(".source-decision-card summary")); const detail = get<HTMLDetailsElement>(".source-decision-card details"); assert(detail.open, "Source disclosure stayed closed"); assert(detail.textContent?.includes("24 source records"), "Full source count lost"); assert(detail.textContent?.includes("reference preview"), "Reference truncation not disclosed"); assert(detail.textContent?.includes("2026-10-05 to 2026-10-11"), "Original period changed"); assert(detail.textContent?.includes("Seven-day cash obligations"), "Formula absent"); const missing = document.querySelectorAll(".source-decision-card")[2]; assert(missing.textContent?.includes("current bank cash"), "Missing input explanation absent"); }],
    ["Evidence navigation returns the exact card and original source date", async () => { await click(get(".source-decision-actions button")); assert(selected?.id === "fixture-bills", "Wrong evidence card"); assert(selected?.evidence.asOf === "2026-10-11", "Original source date changed"); }],
    ["Pending action prevents duplicate same-turn activation", async () => { const button = get<HTMLButtonElement>(".source-decision-primary"); await act(async () => { button.click(); button.click(); }); assert(calls === 1, "Same-turn activations called the action more than once"); assert(button.disabled && button.textContent?.includes("Opening"), "Pending action state absent"); }],
    ["Rejected action retains source context and hides internal details", async () => { await act(async () => { rejectStep(new Error("PRIVATE_FIXTURE_PROVIDER_ERROR")); }); assert(get(".source-decision-error").textContent?.includes("records were not changed"), "Recovery missing"); assert(!document.body.textContent?.includes("PRIVATE_FIXTURE_PROVIDER_ERROR"), "Internal error exposed"); assert(get<HTMLDetailsElement>(".source-decision-card details").open, "Rejected action collapsed source context"); assert(!get<HTMLButtonElement>(".source-decision-primary").disabled, "Recovery left the action blocked"); }],
    ["Retry keeps the original card and clears the error after resolution", async () => { await click(get(".source-decision-primary")); assert(selected?.id === "fixture-bills", "Retry used another card"); assert(selected?.evidence.asOf === "2026-10-11", "Retry changed the source date"); await act(async () => { resolveStep(); }); assert(!document.querySelector(".source-decision-error"), "Successful retry retained the error"); }],
    ["Permission changes remove action controls while preserving source disclosure", async () => { await render(false); assert(!document.querySelector(".source-decision-primary"), "Unauthorized action remained"); assert(document.querySelector(".source-decision-actions button"), "Evidence controls disappeared"); }],
    ["Long retained references fit a 320px container without horizontal overflow", async () => { await render(false, true); await act(async () => { document.querySelectorAll<HTMLDetailsElement>(".source-decision-card details").forEach(detail => { detail.open = true; }); }); const host = get("#decision-test-host"); assert(host.scrollWidth <= host.clientWidth + 1, `Container overflows: ${host.scrollWidth}px inside ${host.clientWidth}px`); }],
  ];
  for (const [name, run] of cases) { try { await run(); results.push({ name, passed: true }); } catch (error) { results.push({ name, passed: false, message: error instanceof Error ? error.message : "Verification failed" }); } }
  await act(async () => root.render(<main className="browser-results"><h1>Decision card browser verification</h1><p>{results.filter(result => result.passed).length} of {results.length} checks passed.</p><ul>{results.map(result => <li key={result.name}>{result.passed ? "PASS" : "FAIL"}: {result.name}{result.message ? ` (${result.message})` : ""}</li>)}</ul></main>));
  document.documentElement.dataset.decisionCardTests = results.every(result => result.passed) ? "passed" : "failed";
}
if (new URLSearchParams(location.search).has("test")) void verify(); else root.render(<Preview/>);
